  return typeof value === 'string' && value.length <= DEAL_NAME_MAX_LENGTH && !/[\r\n]/.test(value);
}

export function renameGame(state: GameState, name: string): GameState {
  return isValidDealName(name) && name !== state.name ? { ...state, name } : state;
}
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { DEAL_NAME_MAX_LENGTH, isValidDealName, renameGame } from './deal-name.ts';
import { activateCard, advanceGame, createGame } from './game.ts';

test('deal names preserve spaces, Unicode and every character except line breaks', () => {
  assert.equal(DEAL_NAME_MAX_LENGTH, 40);
  for (const name of ['', '  Café 😀  ', ' ', '\t', '\u0000', '\u2028\u2029', '<>&"']) {
    assert.equal(isValidDealName(name), true);
    assert.equal(renameGame(createGame('np1-4-1'), name).name, name);
  }
  for (const name of ['a\nb', 'a\rb', '\r\n', 'a'.repeat(41), '😀'.repeat(21)]) {
    assert.equal(isValidDealName(name), false);
  }
  for (const value of [null, undefined, 1, {}, [], false]) {
    assert.equal(isValidDealName(value), false);
  }
});

test('the name limit counts UTF-16 code units, including surrogate pairs', () => {
  for (const name of ['a'.repeat(40), '😀'.repeat(20), '😀'.repeat(19) + 'ab']) {
    assert.equal(isValidDealName(name), true);
    assert.equal(renameGame(createGame('np1-4-1'), name).name, name);
    assert.equal(isValidDealName(name + 'x'), false);
  }
});

test('renaming changes only the name and invalid edits keep the original state', () => {
  const state = advanceGame(activateCard(activateCard(createGame('np1-4-1'), 0), 1), 100.5);
  assert.equal(state.name, '');
  const named = renameGame(state, '  Café  ');
  assert.deepEqual(named, { ...state, name: '  Café  ' });
  assert.equal(named.deck, state.deck);
  assert.equal(named.matched, state.matched);
  assert.equal(named.selection, state.selection);
  assert.equal(renameGame(named, named.name), named);
  for (const name of ['a\nb', 'a\rb', 'x'.repeat(41)]) {
    assert.equal(renameGame(named, name), named);
  }
  assert.deepEqual(renameGame(named, ''), state);
});

test('play preserves a deal name and a newly created deal starts unnamed', () => {
  const named = renameGame(createGame('np1-4-1'), 'Café');
  const first = activateCard(named, 0);
  const mismatch = activateCard(first, 1);
  const closed = advanceGame(mismatch, 800);
  const matched = activateCard(activateCard(closed, 0), 11);
  for (const state of [first, mismatch, closed, matched]) assert.equal(state.name, 'Café');
  assert.equal(createGame(named.boardCode).name, '');
});
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { activateCard, advanceGame, createGame } from './game.ts';
import { renameGame } from './deal-name.ts';
import { decodeSnapshot, encodeSnapshot, NAMED_SNAPSHOT_VERSION } from './snapshot.ts';
import { replayGame } from './replay.ts';

const UNNAMED = {
  version: 1,
  boardCode: 'np1-4-1',
  matched: [],
  selection: { kind: 'closed' },
  moves: 0,
  elapsedMs: 0,
  started: false,
};
const NAMED = { ...UNNAMED, version: 2, name: '  Café 😀  ' };

test('snapshot schemas accept every field first and reversed object properties', () => {
  for (const snapshot of [UNNAMED, NAMED]) {
    const entries = Object.entries(snapshot);
    const expected = { ...createGame('np1-4-1'), name: snapshot.version === 2 ? NAMED.name : '' };
    for (let index = 0; index < entries.length; index += 1) {
      const rotated = [...entries.slice(index), ...entries.slice(0, index)];
      assert.deepEqual(decodeSnapshot(JSON.stringify(Object.fromEntries(rotated))), expected);
    }
    assert.deepEqual(
      decodeSnapshot(JSON.stringify(Object.fromEntries(entries.reverse()))),
      expected,
    );
  }
});

test('named snapshots restore the documented progress and preserve exact name text', () => {
  const text =
    '{"version":2,"name":"Café","boardCode":"np1-4-1","matched":[],"selection":{"kind":"one","index":2},"moves":0,"elapsedMs":0,"started":true}';
  const state = decodeSnapshot(text);
  assert.deepEqual(state, renameGame(activateCard(createGame('np1-4-1'), 2), 'Café'));
  for (const name of ['  Café 😀  ', ' ', '\t', '\u0000', '\u2028\u2029', '😀'.repeat(20)]) {
    const named = renameGame(createGame('np1-4-1'), name);
    assert.deepEqual(decodeSnapshot(encodeSnapshot(named)), named);
  }
});

test('named progress exports version two and clearing its name restores the exact version one schema', () => {
  assert.equal(NAMED_SNAPSHOT_VERSION, 2);
  const named = renameGame(createGame('np1-4-1'), NAMED.name);
  assert.deepEqual(JSON.parse(encodeSnapshot(named)), NAMED);
  assert.deepEqual(JSON.parse(encodeSnapshot(renameGame(named, ''))), UNNAMED);
  assert.equal(decodeSnapshot(JSON.stringify(UNNAMED))?.name, '');
});

test('snapshot names reject invalid types, empty names, line breaks and excess UTF-16 units', () => {
  for (const name of [
    null,
    1,
    false,
    {},
    [],
    '',
    '\r',
    '\n',
    'a\r\nb',
    'a'.repeat(41),
    '😀'.repeat(21),
  ]) {
    assert.equal(decodeSnapshot(JSON.stringify({ ...NAMED, name })), null);
  }
});

test('both snapshot versions require exact keys and reject unsupported versions', () => {
  for (const snapshot of [UNNAMED, NAMED]) {
    for (const field of Object.keys(snapshot)) {
      const withoutField = Object.fromEntries(
        Object.entries(snapshot).filter(([key]) => key !== field),
      );
      assert.equal(decodeSnapshot(JSON.stringify(withoutField)), null);
    }
    assert.equal(decodeSnapshot(JSON.stringify({ ...snapshot, extra: true })), null);
    for (const version of [0, 3, -1, '1', null]) {
      assert.equal(decodeSnapshot(JSON.stringify({ ...snapshot, version })), null);
    }
  }
  assert.equal(decodeSnapshot(JSON.stringify({ ...UNNAMED, name: 'Café' })), null);
  assert.equal(decodeSnapshot(JSON.stringify({ ...UNNAMED, version: 2 })), null);
});

test('named imports retain strict progress validation independent of property order', () => {
  for (const fields of [
    { matched: [0] },
    { matched: [0, 1], moves: 1, started: true },
    { selection: { kind: 'closed', extra: true } },
    { elapsedMs: 0.5 },
    { elapsedMs: 360000000 },
    { moves: 1000000 },
    { started: true },
  ]) {
    const value = { ...NAMED, ...fields };
    assert.equal(
      decodeSnapshot(JSON.stringify(Object.fromEntries(Object.entries(value).reverse()))),
      null,
    );
  }
  const value = { ...NAMED, selection: { index: 2, kind: 'one' }, started: true };
  assert.equal(decodeSnapshot(JSON.stringify(value))?.selection.kind, 'one');
});

test('named exports retain fractional clock rounding and pending mismatch bounds', () => {
  const mismatch = activateCard(activateCard(createGame('np1-4-1'), 0), 1);
  const state = renameGame(advanceGame(mismatch, 799.75), 'Café');
  const restored = decodeSnapshot(encodeSnapshot(state));
  assert.equal(restored?.name, 'Café');
  assert.equal(restored?.elapsedMs, 799);
  assert.deepEqual(restored?.selection, { kind: 'mismatch', first: 0, second: 1, remainingMs: 1 });
});

test('named snapshots enforce the UTF-8 byte limit with multibyte names', () => {
  const text = JSON.stringify(NAMED);
  const padded = text + ' '.repeat(65536 - Buffer.byteLength(text, 'utf8'));
  assert.equal(decodeSnapshot(padded)?.name, NAMED.name);
  assert.equal(decodeSnapshot(padded + ' '), null);
});

test('replays stay unnamed and export version one snapshots', () => {
  const result = replayGame('{"version":1,"boardCode":"np1-4-1","actions":[],"endMs":0}');
  assert.ok(result);
  assert.equal(result.name, '');
  assert.deepEqual(JSON.parse(encodeSnapshot(result)), UNNAMED);
});
# Neon Pairs

Neon Pairs is a memory game that runs offline from one HTML file and keeps local best moves for each board size.

You can repeat a deal with its board code, save progress as a snapshot or run timed actions through the replay command.

Status: implements product spec version 2.2.

## Install

Use the named test combination, Node 26.12.1, npm 11.20.0 and Playwright 1.64.1 with Chromium 156.0.8078.4. From this folder, install the locked tools:

```powershell
npm ci --cache .npm-cache
$env:PLAYWRIGHT_BROWSERS_PATH = Join-Path $PWD '.playwright-browsers'
$env:TEMP = Join-Path $PWD '.browser-work'
$env:TMP = $env:TEMP
New-Item -ItemType Directory -Force -Path $env:TEMP | Out-Null
npm exec --cache .npm-cache -- playwright install chromium
```

These settings keep the browser download and temporary files inside the project. Browser tests use fresh contexts. They stop their browser and local HTTP server when they finish.

## Play

Run `npm run build`, then open `dist/index.html` from disk. The game makes no network requests. To keep saved sizes and scores on a stable HTTP origin, run `npm run dev`. Stop it when you finish.

Use Grid size to choose a board. Reveal two cards with a click, tap, Enter or Space. Arrow keys move board focus. Other keys stay with the browser. Tab leaves the board. New Game gives another deal. Restart repeats the current deal.

Open Reproduce a game to load a board code or export progress. Loading an unfinished snapshot pauses it. Resume returns focus to the remembered card and continues the remaining mismatch interval. A completed snapshot loads as completed without Resume. Elapsed time stops at 359999999ms while play continues. The minutes and seconds display reaches 5999:59. Moves stop at 999999. Matching and victory continue at that count. Saved bests use the same move limit.

## Replay

Run `npm run --silent replay -- PATH` with a version 1 replay JSON file. Valid input prints only its final version 1 snapshot JSON to stdout and exits 0. Invalid input prints nothing to stdout, writes a message to stderr and exits nonzero. The command's silent flag suppresses its npm banner so stdout stays JSON. Other npm commands keep their errors and warnings. Replay timestamps can reach the safe integer limit. Elapsed time uses the same cap as browser play.

## Check

Run the checks from this folder:

```powershell
npm run typecheck
npm test
$env:NEON_PAIRS_NAMED_COMBINATION = '1'
npm run test:e2e
npm run format:check
```

`npm test` runs the unit and static checks with Vitest 5.0.5. `test:e2e` type checks and builds current source before opening the new HTML. It also builds the face sheet and session harness as separate diagnostic entries. The game distribution contains no diagnostic entry.

The browser command writes the Node, npm, Playwright and Chromium versions it ran on to `test-results/browser-runtime.json`. With `NEON_PAIRS_NAMED_COMBINATION` set to `1`, it also fails unless they match the named combination. Use the flag for named-combination evidence. Other supported runtimes, such as Node 24.19, run without it.

The locked install, type check, Vitest unit tests, build from current source and Chromium journeys have passed on the named combination with the flag set. Other versions have no test record here.

## Accessibility

Keyboard, card names, atomic turn feedback, reduced motion, touch scrolling and the equivalent zoom layout at 640x400 CSS pixels with device scale 2 have browser checks. The diagnostic face sheet draws all 128 faces at 44px.

Playwright checks Chromium's accessibility tree through a complete keyboard journey. It checks controls, card names, states, turn results, the final summary, Tab exit and New Game. The developer provides this tree evidence and the tool record. You confirm spoken output during acceptance with your screen reader.

Tree record: Chromium 156.0.8078.4 and Playwright 1.64.1. Screen reader: not run. Spoken journey: user acceptance.

Delivered projects from document setups keep the product specification in `docs/`.

Follow the requirements in docs/ for this project.
import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}
